import sys
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        nums = list(map(int, line.split()))
        if not nums:
            continue
        positive_nums = [abs(n) for n in nums]
        if 0 in positive_nums:
            g = 0
            l = 0
        else:
            g = positive_nums[0]
            l = positive_nums[0]
            for n in positive_nums[1:]:
                g = math.gcd(g, n)
                l = l * n // math.gcd(l, n)
        print(g, l)


if __name__ == "__main__":
    main()
